import{_ as t,a,o as n,a6 as s}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Generate Sitemap","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"generate","title":"Generate Sitemap","description":"Build the XML files for a sitemap. Send an empty body — the id comes from the URL.","query":"curl -X POST \\"https://your-domain.com/api/admin/marketing/sitemaps/1/generate\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","variables":"{}\\n","response":"{\\n  \\"sitemapId\\": 1,\\n  \\"generatedFiles\\": [\\n    {\\n      \\"channelId\\": 1,\\n      \\"channelCode\\": \\"default\\",\\n      \\"hostname\\": \\"https://example.com\\",\\n      \\"index\\": \\"sitemaps/default/sitemap-1-1.xml\\",\\n      \\"sitemaps\\": [\\n        \\"sitemaps/default/sitemap-1-1-1.xml\\"\\n      ]\\n    }\\n  ],\\n  \\"urls\\": [\\n    \\"https://example.com/storage/sitemaps/default/sitemap-1-1.xml\\"\\n  ],\\n  \\"indexFile\\": null,\\n  \\"generatedSitemaps\\": [],\\n  \\"generatedAt\\": \\"2026-06-23T13:00:00+05:30\\",\\n  \\"message\\": \\"Sitemap generated successfully.\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/marketing/search-seo/sitemaps-generate.md","filePath":"api/rest-api/admin/marketing/search-seo/sitemaps-generate.md","lastUpdated":1789385991000}'),i={name:"api/rest-api/admin/marketing/search-seo/sitemaps-generate.md"};function d(r,e,o,l,h,c){return n(),a("div",null,e[0]||(e[0]=[s('<h1 id="generate-sitemap" tabindex="-1">Generate Sitemap <a class="header-anchor" href="#generate-sitemap" aria-label="Permalink to &quot;Generate Sitemap&quot;">​</a></h1><p>Builds the XML files for a sitemap — the <strong>Generate</strong> row action on the admin <strong>Marketing → Search &amp; SEO → Sitemaps</strong> screen. Saving a sitemap does not build its files, so this is the explicit step that produces them.</p><p>New here? Read the <a href="/api/rest-api/admin/marketing/search-seo/sitemaps/">Sitemaps overview</a> for what a sitemap does and how its fields behave.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/marketing/sitemaps/{id}/generate</code></td><td>POST</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.search_seo.sitemaps.edit</code> permission.</li><li>Send an <strong>empty body</strong> — the sitemap id comes from the URL.</li><li>Runs once per channel the sitemap covers: for each, it walks that channel&#39;s root category subtree and the products and pages assigned to it, then writes an index file plus the per-batch XML files under <code>sitemaps/{channel}/</code>, using the channel&#39;s own hostname for the URLs inside them.</li><li>The response carries the generated file paths once the build finishes, grouped by channel.</li><li>A sitemap that covers no channel has nothing to generate and is refused with a <code>422</code> — assign at least one channel first.</li><li>If sitemap generation is disabled in the store configuration, the request still succeeds but produces no files (<code>generatedFiles</code> empty).</li></ul><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>sitemapId</code></td><td>int</td><td>Id of the sitemap that was generated</td></tr><tr><td><code>generatedFiles</code></td><td>object[]</td><td>What the run wrote, one entry per channel: <code>channelId</code>, <code>channelCode</code>, <code>hostname</code>, <code>index</code>, <code>sitemaps[]</code></td></tr><tr><td><code>urls</code></td><td>string[]</td><td>Public index URL per channel — the link to submit to a search engine</td></tr><tr><td><code>indexFile</code></td><td>string</td><td>Index path of a sitemap generated before generation became channel-aware. <code>null</code> for anything generated since</td></tr><tr><td><code>generatedSitemaps</code></td><td>string[]</td><td>Child paths of a sitemap generated before generation became channel-aware. Empty for anything generated since</td></tr><tr><td><code>generatedAt</code></td><td>string</td><td>Timestamp of this generate run</td></tr><tr><td><code>message</code></td><td>string</td><td>Success message</td></tr></tbody></table>',9)]))}const g=t(i,[["render",d]]);export{m as __pageData,g as default};
